-- Player-facing text (src/content/text-fields.ts): revision 1 of each document.
-- Never overwrites a document that already has a row (text saved on the admin page).

-- level:2.3
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.3', 1, '{"location":"Vành Sentinel · Bãi Container","briefing":"[NHẬT KÝ ĐIỀU KHIỂN – ĐÈN PHA BÃI CONTAINER]\nĐèn pha báo góc của nó theo độ, đo từ mép trái bãi. Mỗi lần đèn dừng là một tình huống.\nGóc dưới 90 là lúc đèn chiếu nửa trái bãi, nên Kai phải sang phải. Từ 90 trở lên, kể cả đúng 90 khi đèn chiếu thẳng xuống lối giữa, là lúc đèn chiếu nửa phải, nên Kai sang trái.\nỞ mỗi tình huống, bộ điều khiển ghi góc đèn vào nhật ký, dù Kai chạy về hướng nào.","task_steps":["Bấm CHẠY với mã có sẵn. Sau mỗi lượt, những dòng mờ trong editor là những dòng không chạy ở tình huống đang hiện.","Sửa để ở mọi tình huống, `huong` có đúng một hướng theo luật ở ô Mục tiêu, kể cả khi góc đèn đúng bằng mốc.","Dòng ghi góc đèn phải in ra ở mọi tình huống. Không in thêm dòng nào khác. Không sửa dòng khóa.","Hoàn thành khi cả 2 mục tiêu chuyển thành xanh ở cả ba tình huống. Dùng không quá 3 câu lệnh và vẫn đúng khi OMNI đổi góc quét thì được thêm sao."],"objectives":[{"var":"huong","label":"Hướng Kai chạy: SANG PHAI khi góc đèn dưới 90, còn lại SANG TRAI"},{"line":1,"label":"GOC DEN:, một dấu cách, rồi góc đèn"}],"hints":["Sau mỗi lượt, nhìn các dòng mờ: đó là những dòng không chạy ở tình huống đang hiện. Dòng ghi góc đèn đang nằm trong khối nào? Và khi góc đúng bằng 90, còn dòng gán hướng nào sáng không?","Chỉ cần kiểm góc đèn một lần. Điều kiện đúng thì Kai đi một hướng, mọi trường hợp còn lại thì đi hướng kia, không cần viết điều kiện thứ hai. Dòng ghi góc đặt sau khối, sát lề trái.\n\nnếu  <góc dưới mốc>\n    hướng = <một hướng>\ncòn lại\n    hướng = <hướng kia>\nin   GOC DEN: <góc>","Mảnh tài liệu Python còn đọc được:\nif diem >= 5:\n    ket_qua = \"DAT\"\nelse:                    → else không có điều kiện, nhận mọi trường hợp còn lại\n    ket_qua = \"CHUA DAT\"\nprint(ket_qua)           → sát lề trái, sau khối: luôn chạy\nDòng thụt lề thuộc khối ngay trên nó và chỉ chạy khi khối đó chạy.\nGán biến ở cả hai nhánh thì sau khối biến luôn có giá trị."],"reactions":{"entry":"Bãi Container. Đèn pha trên tháp quét qua quét lại, mỗi lần dừng là một tình huống. Kai chỉ có hai ngả. Chưa cần sửa gì… bạn chạy một lần rồi nhìn những dòng mờ trong editor.","output_missing":"Ở tình huống {round}, nhật ký góc đèn trống từ dòng {out_line}. Dòng ghi góc chỉ chạy khi khối lệnh chứa nó chạy.","missing_var":"Ở tình huống {round}, không nhánh nào gán {vars}. Kai không có hướng nào để chạy… anh đứng yên giữa lối, ngay dưới đèn.","wrong_branch":"Thứ mã đưa ra là của một tình huống khác. Mã vẫn đi qua một nhánh có thật… chỉ là không đúng với lần đèn dừng này. Nhìn xem ở tình huống trượt, dòng nào còn sáng.","wrong_value":"Ở tình huống {round}, {vars} giữ một hướng không có trong luật. Soát từng chữ với ô Mục tiêu.","type_mismatch":"Ở tình huống {round}, {vars} sai kiểu dữ liệu. Bộ điều khiển chỉ đọc hướng viết bằng chữ.","type_mismatch_value_match":"Ở tình huống {round}, {vars} trông đúng… nhưng sai kiểu dữ liệu. Bộ điều khiển vẫn không đọc được.","output_mismatch":"Ở tình huống {round}, dòng nhật ký thứ {out_line} lệch từ ký tự thứ {col}. Bộ điều khiển không đoán ý… nó ghi đúng những gì nhận được.","output_case_only":"Ở tình huống {round}, dòng nhật ký thứ {out_line} chỉ sai cỡ chữ. Bộ điều khiển phân biệt chữ hoa với chữ thường.","output_extra":"Ở tình huống {round}, nhật ký có thêm {count} dòng mà bộ điều khiển không hỏi. Nó chỉ cần dòng góc đèn.","output_is_label":"Ở tình huống {round}, dòng nhật ký thứ {out_line} ghi nguyên tên một ô nhớ, cả cặp ngoặc nhọn. Bộ điều khiển cần giá trị trong ô đó… không cần cái tên.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Mã chưa chạy… đèn chưa dừng lần nào. Đọc kỹ dòng báo lỗi Python in ra.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng quyết định dòng nào thuộc khối nào.","TypeError":"Dòng {line}. TypeError. Hai giá trị khác kiểu vừa bị ghép vào cùng một phép tính.","ValueError":"Dòng {line}. ValueError. Một giá trị không đổi được sang thứ mã đòi.","NameError":"Dòng {line}. NameError. Mã dùng một cái tên mà chưa nhánh nào gán… hoặc tên đó bị gõ sai.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Giá trị này không có thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Mã dừng giữa chừng ở tình huống {round}. Những dòng sau nó chưa kịp chạy.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ngoài Vành Sentinel, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Góc đèn đã nằm sẵn ở dòng khóa.","system_exit":"Mã tự dừng giữa chừng. Bộ điều khiển không nhận được phần còn lại.","alert_exceeded":"Kai qua được cả ba tình huống. Nhưng mã dùng {count} câu lệnh… Mỗi lần kiểm thêm góc đèn hay đổi hướng giữa chừng là một lần drone có thể nghe thấy.","counter_ValueError":"OMNI đổi nhịp quét. Dòng {line} lỗi: ValueError. Mã không chịu được những góc mới.","counter_error":"OMNI đổi nhịp quét. Dòng {line}: {error_type}. Mã không chạy nổi với những góc mới.","counter_type_mismatch":"OMNI đổi nhịp quét. Với những góc mới, {vars} ra sai kiểu dữ liệu. Bộ điều khiển không đọc được.","wrong_value_counter":"OMNI đổi nhịp quét. Mã của bạn vẫn theo nhịp cũ… đèn dừng ở chỗ mới, và Kai chạy thẳng vào vùng sáng.","counter_timeout":"OMNI đổi nhịp quét. Mã của bạn treo ở những góc mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Kai qua được bãi. Drone không ghi nhận gì.","three_stars":"Đèn đổi nhịp quét… Kai vẫn luôn ở phía tối. Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại từng tình huống trong terminal."},"reaction_variants":{"wrong_branch":"Vẫn là thứ của một tình huống khác. Ở tình huống trượt, dòng nào mờ, dòng nào còn sáng?","missing_var":"Ở tình huống {round}, Kai vẫn không có hướng. Nhìn các dòng gán hướng ở tình huống đó… dòng nào còn sáng?","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem ở mỗi tình huống, mã kiểm góc đèn mấy lần và gán hướng mấy lần."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐỔI NHỊP QUÉT CỦA ĐÈN PHA","outro":"Kai ra tới cuối bãi. Đèn pha vẫn quét, và mỗi lần dừng, nó chiếu đúng vào chỗ anh vừa rời đi. Trong hộp điều khiển đèn còn lưu một bản ghi kiểm thử cũ:","lore_fragment":"KTS-07: Tôi đã cho nó chạy qua mọi nhánh, từng nhánh một. Nhánh nào cũng có lý do. Tôi chỉ ghi lại mỗi nhánh rẽ về đâu, không ghi vì sao. Có những lý do không nên nằm trong nhật ký.","component":"Ngả rẽ","outro_beats":[{"kind":"log","text":"Trên vách một container có ký hiệu trạm R-17 của Mạng Mù, khắc bằng tay. Đã có người qua đây trước Kai."},{"kind":"echo","text":"Vết khắc đã gỉ. Dấu này có từ lâu trước đêm nay… ngoài chuyện đó, tôi không kiểm tra được gì."},{"kind":"kai","text":"Người khắc dấu này có tới được bên kia không?"}],"knowledge_summary":{"title":"`else` và dòng sau khối lệnh","sections":[{"heading":"`if` / `else`: đúng một nhánh chạy","body":"`if` kiểm một điều kiện. Điều kiện đúng thì khối thụt lề dưới `if` chạy, sai thì khối dưới `else` chạy. Mỗi lần chạy, đúng một trong hai khối chạy: không bao giờ cả hai, cũng không bao giờ không khối nào."},{"heading":"`else` không có điều kiện","body":"`else` nhận mọi trường hợp mà `if` không nhận, kể cả giá trị nằm đúng trên mốc. Sau `else` chỉ viết dấu hai chấm, không viết điều kiện. Ở ví dụ, `diem` bằng đúng 5 nên `diem < 5` sai và khối `else` chạy."},{"heading":"Dòng sau khối luôn chạy","body":"Dòng viết sát lề trái sau khối `if`/`else` không thuộc nhánh nào. Nó chạy sau khi một nhánh đã chạy xong, dù đó là nhánh nào."},{"heading":"Thụt lề quyết định khối","body":"Ở đây dòng `print(\"DA CHAM XONG\")` thụt lề bằng thân `else`, nên nó thuộc khối `else`. Điểm 8 đi vào nhánh `if`, nên dòng đó không chạy. So với ví dụ trước, hai dòng này chỉ khác khoảng trắng đầu dòng."},{"heading":"Hai `if` rời so với `if` / `else`","body":"Hai `if` rời là hai lần kiểm riêng. Viết lệch ở giá trị bằng mốc thì có giá trị không lọt vào `if` nào (như 5 ở đây), hoặc lọt vào cả hai. `if`/`else` chỉ kiểm một lần và không bao giờ để hở. Lần kiểm thứ hai cũng tốn thêm một câu lệnh."},{"heading":"Gán ở cả hai nhánh","body":"Gán `ket_qua` trong cả hai nhánh thì sau khối biến luôn có giá trị, dù nhánh nào chạy. Một dòng `print` sau khối là đủ để in nó."}],"mistakes":[{"code":"diem = 7\nif diem >= 5:\n    print(\"DAT\")\nelse diem < 5:\n    print(\"CHUA DAT\")","explain":"`else` không nhận điều kiện. Python đọc tới `diem` sau `else` thì báo thiếu dấu hai chấm. Viết `else:` và để `else` tự nhận mọi trường hợp còn lại."},{"code":"diem = 7\nif diem >= 5:\n    print(\"DAT\")\nelse:\nprint(\"CHUA DAT\")","explain":"Thân `else` phải thụt lề vào trong, như thân `if`. Dòng `print` nằm sát lề trái nên Python thấy `else:` không có khối nào."},{"code":"diem = 5\nif diem < 5:\n    ket_qua = \"CHUA DAT\"\nif diem > 5:\n    ket_qua = \"DAT\"\nprint(ket_qua)","explain":"Với `diem` bằng 5, không điều kiện nào đúng, nên không dòng nào gán `ket_qua`. Dòng `print` dùng một tên chưa có. Dùng `if`/`else` để luôn có một nhánh chạy."},{"code":"diem = 8\nif diem >= 5:\n    ket_qua = \"DAT\"\nelse:\n    ket_qua = \"CHUA DAT\"\n    print(ket_qua)","explain":"Dòng `print` thụt lề nên nằm trong khối `else` và chỉ chạy khi điểm chưa đạt. Điểm 8 đi vào nhánh `if`, chương trình chạy xong mà không in gì. Đưa dòng `print` ra sát lề trái, sau khối."}],"next":"Màn sau có nhiều hơn hai ngả. Bạn sẽ xét lần lượt từng mức: mức nào đúng trước thì nhánh đó chạy."}}', '2026-10-29T19:59:23.227Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.3' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
